trait ServiceApi { def call(request: Request): Response }

trait Tracing extends ServiceApi {
  abstract override def call(request: Request): Response = {
    val started = System.nanoTime()
    try super.call(request)          // next link, eventually the real service
    finally metrics.record("call", System.nanoTime() - started)
  }
}

val svc: ServiceApi = new RealService with Tracing with RateLimit
